svg.script:
  (() => {
      const CELL_SIZE = 128;
      const TILE_SIZE = 64;

      for (const icon of document.querySelectorAll("svg[data-cell]"))
      {
          const cell = icon.getAttribute("data-cell");
          const m = /^\s*(\d+)\s*,\s*(\d+)\s*$/.exec(cell);

          if (!m)
              throw new Error(`Invalid data-cell on ${icon.id}: "${cell}"`);

          const cellX = Number(m[1]);
          const cellY = Number(m[2]);
          const size = Number(icon.getAttribute("data-size") || CELL_SIZE);

          let subX = 0;
          let subY = 0;

          if (size === TILE_SIZE)
          {
              const sub = icon.getAttribute("data-sub");
              const s = /^\s*([01])\s*,\s*([01])\s*$/.exec(sub || "");

              if (!s)
                  throw new Error(`Invalid data-sub on ${icon.id}`);

              subX = Number(s[1]);
              subY = Number(s[2]);

              icon.setAttribute("x", String(cellX * CELL_SIZE + subX * TILE_SIZE));
              icon.setAttribute("y", String(cellY * CELL_SIZE + subY * TILE_SIZE));
              icon.setAttribute("width", "64");
              icon.setAttribute("height", "64");
              icon.style.width = "64px";
              icon.style.height = "64px";
              icon.setAttribute("viewBox", "32 32 64 64");
          }
          else
          {
              icon.setAttribute("x", String(cellX * CELL_SIZE));
              icon.setAttribute("y", String(cellY * CELL_SIZE));
          }
      }
  })();
